.table th, .table td { padding: 8px; border-bottom: 1px solid var(--border); text-align: left; }
.table th { color: var(--muted); font-weight: 600; }
.tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 10px; }
.tab {
  padding: 7px 10px;
  border-radius: 7px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--muted);
  font-size: 12px;
  cursor: pointer;
}
.tab.active { color: var(--text); border-color: var(--accent); }
.spark { height: 30px; width: 100px; background: linear-gradient(180deg,#1e293b,#0f172a); border-radius: 4px; position: relative; overflow: hidden; }
.spark::after { content:""; position:absolute; inset: 8px 5px; border-bottom:2px solid var(--green); border-radius: 999px; transform: skewX(-18deg); }
.chart-layout { display: grid; grid-template-columns: 280px 1fr 340px; gap: 10px; }
.watchlist-group { margin-bottom: 8px; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
.watchlist-header { padding: 8px 10px; background: #171b2e; cursor: pointer; font-size: 13px; }
.watchlist-body { display: none; }
.watchlist-group.open .watchlist-body { display: block; }
.toolbar { display: flex; gap: 8px; margin-bottom: 8px; flex-wrap: wrap; }
.btn { background: var(--panel-2); border: 1px solid var(--border); color: var(--text); padding: 6px 9px; border-radius: 6px; font-size: 12px; cursor: pointer; }
.chart-box { height: 520px; border: 1px solid var(--border); border-radius: 10px; background: linear-gradient(180deg,#0f172a,#111827); position: relative; overflow: hidden; }
.candles { position: absolute; inset: 16px; background-image: repeating-linear-gradient(to right, rgba(148,163,184,.12) 0 1px, transparent 1px 24px), repeating-linear-gradient(to bottom, rgba(148,163,184,.08) 0 1px, transparent 1px 48px); }
.kline { position: absolute; bottom: 20px; width: 8px; background: var(--green); }
.kline.red { background: var(--red); }
.metric { display: grid; grid-template-columns: 1fr auto; padding: 6px 0; border-bottom: 1px solid var(--border); font-size: 13px; }
.footer-note { color: var(--muted); font-size: 12px; margin-top: 8px; }
@media (max-width: 1180px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { position: static; height: auto; }
  .chart-layout { grid-template-columns: 1fr; }
  .grid-4, .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .search { min-width: auto; width: 100%; }
}
